package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	_ "github.com/shopspring/decimal"
)

type DateRec struct { // 01 DATE-REC, 12 bytes
	DtId   string // PIC X(4) @0 len=4
	DtYyyy int64  // PIC 9(4) @4 len=4
	DtMm   int64  // PIC 9(2) @8 len=2
	DtDd   int64  // PIC 9(2) @10 len=2
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N"  // PIC X len=1 = "N"
var WsLeapFlag string = "N" // PIC X len=1 = "N"
var WsQ int64 = 0           // PIC 9(4) len=4 = 0
var WsR4 int64 = 0          // PIC 9(3) len=3 = 0
var WsR100 int64 = 0        // PIC 9(3) len=3 = 0
var WsR400 int64 = 0        // PIC 9(3) len=3 = 0
var WsMaxDay int64 = 0      // PIC 99 len=2 = 0
var WsValid int64 = 0       // PIC 99 len=2 = 0
var WsBadMonth int64 = 0    // PIC 99 len=2 = 0
var WsBadDay int64 = 0      // PIC 99 len=2 = 0

var dateRec DateRec

var dateLines []string
var dateIdx int
var dateOpen bool

func isInputDone() bool { return WsEofFlag == "Y" }
func isLeap() bool      { return WsLeapFlag == "Y" }

func parseNum(s string) int64 {
	s = strings.TrimSpace(s)
	if s == "" {
		return 0
	}
	var v int64
	for _, ch := range s {
		if ch >= '0' && ch <= '9' {
			v = v*10 + int64(ch-'0')
		} else {
			// non-digit: treat as zero per COBOL numeric DISPLAY tolerance
			// ignore sign/others; if truly bad, return what we have
		}
	}
	return v
}

func padRight(s string, n int) string {
	if len(s) >= n {
		return s[:n]
	}
	return s + strings.Repeat(" ", n-len(s))
}

func fmtN(v int64, w int) string {
	// keep low-order digits
	m := int64(1)
	for i := 0; i < w; i++ {
		m *= 10
	}
	v = v % m
	if v < 0 {
		v += m
	}
	s := fmt.Sprintf("%d", v)
	if len(s) > w {
		s = s[len(s)-w:]
	}
	if len(s) < w {
		s = strings.Repeat("0", w-len(s)) + s
	}
	return s
}
func fmtX(s string, w int) string {
	return padRight(s, w)
}

func openDateFile() {
	f, err := os.Open("input.dat")
	if err != nil {
		// COBOL OPEN INPUT on missing file: treat as empty (EOF immediate)
		// If error other than not-exist, report to stderr
		if os.IsNotExist(err) {
			dateLines = nil
			dateIdx = 0
			dateOpen = true
			return
		}
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	defer f.Close()
	sc := bufio.NewScanner(f)
	// allow long lines
	sc.Buffer(make([]byte, 0, 64*1024), 10*1024*1024)
	dateLines = nil
	for sc.Scan() {
		line := sc.Text()
		dateLines = append(dateLines, line)
	}
	if err := sc.Err(); err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	dateIdx = 0
	dateOpen = true
}

func closeDateFile() {
	dateOpen = false
}

func MainPara() {
	openDateFile()
	ReadPara()
	for !isInputDone() {
		ProcessPara()
	}
	closeDateFile()
	// DISPLAY "VALID: " WS-VALID " BAD MONTH: " WS-BAD-MONTH " BAD DAY: " WS-BAD-DAY
	fmt.Println("VALID: "+fmtN(WsValid, 2)+" BAD MONTH: "+fmtN(WsBadMonth, 2)+" BAD DAY: "+fmtN(WsBadDay, 2))
}

func ReadPara() {
	if dateIdx >= len(dateLines) {
		WsEofFlag = "Y"
		return
	}
	line := dateLines[dateIdx]
	dateIdx++
	// pad with spaces on right to record length 12
	if len(line) < 12 {
		line = line + strings.Repeat(" ", 12-len(line))
	} else if len(line) > 12 {
		line = line[:12]
	}
	dateRec.DtId = line[0:4]
	dateRec.DtYyyy = parseNum(line[4:8])
	dateRec.DtMm = parseNum(line[8:10])
	dateRec.DtDd = parseNum(line[10:12])
}

func ProcessPara() {
	LeapPara()
	if dateRec.DtMm < 1 || dateRec.DtMm > 12 {
		WsBadMonth = (WsBadMonth + 1) % 100
		fmt.Println(fmtX(dateRec.DtId, 4)+" BAD MONTH "+fmtN(dateRec.DtMm, 2))
	} else {
		DaysPara()
		if dateRec.DtDd < 1 || dateRec.DtDd > WsMaxDay {
			WsBadDay = (WsBadDay + 1) % 100
			fmt.Println(fmtX(dateRec.DtId, 4)+" BAD DAY "+fmtN(dateRec.DtDd, 2)+" MAX "+fmtN(WsMaxDay, 2))
		} else {
			WsValid = (WsValid + 1) % 100
			fmt.Println(fmtX(dateRec.DtId, 4)+" VALID "+fmtN(dateRec.DtYyyy, 4)+"-"+fmtN(dateRec.DtMm, 2)+"-"+fmtN(dateRec.DtDd, 2))
		}
	}
	ReadPara()
}

func LeapPara() {
	// DIVIDE DT-YYYY BY 4 GIVING WS-Q REMAINDER WS-R4 etc.
	// All values non-negative
	q4 := dateRec.DtYyyy / 4
	r4 := dateRec.DtYyyy % 4
	q100 := dateRec.DtYyyy / 100
	r100 := dateRec.DtYyyy % 100
	q400 := dateRec.DtYyyy / 400
	r400 := dateRec.DtYyyy % 400
	// Last DIVIDE leaves its quotient in WS-Q
	WsQ = q400 % 10000
	WsR4 = r4 % 1000
	WsR100 = r100 % 1000
	WsR400 = r400 % 1000
	_ = q4
	_ = q100
	if WsR4 == 0 && (WsR100 != 0 || WsR400 == 0) {
		WsLeapFlag = "Y"
	} else {
		WsLeapFlag = "N"
	}
}

func DaysPara() {
	switch dateRec.DtMm {
	case 2:
		if isLeap() {
			WsMaxDay = 29
		} else {
			WsMaxDay = 28
		}
	case 4, 6, 9, 11:
		WsMaxDay = 30
	default:
		WsMaxDay = 31
	}
}

func main() {
	MainPara()
}
